// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title NRIVotingSystem
 * @dev Sovereign, tamper-proof electronic voting smart contract for Overseas (NRI) Indian Elections.
 * Guarantees secret ballot, consensus-level double-voting prevention, and transparent tallying.
 */
contract NRIVotingSystem {
    address public electionAuthority;
    string public electionTitle;
    bool public isElectionActive;
    uint256 public electionStartTime;
    uint256 public electionEndTime;

    struct Candidate {
        string candidateId;
        string name;
        string partyName;
        string electionType; // "assembly" or "parliament"
        string constituency;
        uint256 voteCount;
        bool exists;
    }

    struct VoteSlip {
        bytes32 voterCommitment;
        string candidateId;
        string electionType;
        string constituency;
        uint256 blockNumber;
        uint256 timestamp;
    }

    // Mapping: voterCommitment => bool (Strict double voting prevention)
    mapping(bytes32 => bool) public hasVoted;

    // Mapping: candidateId => Candidate
    mapping(string => Candidate) public candidates;
    string[] public candidateIds;

    // Constituency vote tallies: constituency => electionType => totalVotes
    mapping(string => mapping(string => uint256)) public constituencyTotalVotes;

    // Total votes recorded across entire election
    uint256 public totalVotesRecorded;

    // Events
    event VoteStamped(
        bytes32 indexed voterCommitment,
        string indexed candidateId,
        string electionType,
        string constituency,
        uint256 blockNumber,
        uint256 timestamp
    );

    event CandidateRegistered(
        string candidateId,
        string name,
        string partyName,
        string electionType,
        string constituency
    );

    event ElectionStatusChanged(bool active, uint256 startTime, uint256 endTime);

    error OnlyElectionAuthority();
    error DoubleVotingProhibited(bytes32 commitment);
    error CandidateNotFound(string candidateId);
    error ElectionWindowClosed();

    modifier onlyAuthority() {
        if (msg.sender != electionAuthority) {
            revert OnlyElectionAuthority();
        }
        _;
    }

    constructor(string memory _title) {
        electionAuthority = msg.sender;
        electionTitle = _title;
        isElectionActive = true;
        electionStartTime = block.timestamp;
        electionEndTime = block.timestamp + 365 days; // Default open window
    }

    /**
     * @dev Election Authority starts or updates the election window
     */
    function setElectionSchedule(
        bool _active,
        uint256 _startTime,
        uint256 _endTime
    ) external onlyAuthority {
        isElectionActive = _active;
        electionStartTime = _startTime;
        electionEndTime = _endTime;
        emit ElectionStatusChanged(_active, _startTime, _endTime);
    }

    /**
     * @dev Register a candidate on-chain
     */
    function registerCandidate(
        string memory _candidateId,
        string memory _name,
        string memory _partyName,
        string memory _electionType,
        string memory _constituency
    ) external onlyAuthority {
        if (!candidates[_candidateId].exists) {
            candidates[_candidateId] = Candidate({
                candidateId: _candidateId,
                name: _name,
                partyName: _partyName,
                electionType: _electionType,
                constituency: _constituency,
                voteCount: 0,
                exists: true
            });
            candidateIds.push(_candidateId);
            emit CandidateRegistered(_candidateId, _name, _partyName, _electionType, _constituency);
        }
    }

    /**
     * @dev Cast an anonymized vote onto the blockchain
     * @param _voterCommitment Keccak256 hash of (Aadhaar + ElectionType + Salt)
     * @param _candidateId Candidate identifier
     * @param _electionType "assembly" or "parliament"
     * @param _constituency Constituency name
     */
    function castVote(
        bytes32 _voterCommitment,
        string memory _candidateId,
        string memory _electionType,
        string memory _constituency
    ) external onlyAuthority returns (bool) {
        if (!isElectionActive) {
            revert ElectionWindowClosed();
        }

        // 1. Consensus-level double voting guard
        if (hasVoted[_voterCommitment]) {
            revert DoubleVotingProhibited(_voterCommitment);
        }

        // 2. Candidate existence check
        if (!candidates[_candidateId].exists) {
            // Auto-register candidate if not present on-chain
            candidates[_candidateId] = Candidate({
                candidateId: _candidateId,
                name: "Candidate",
                partyName: "Party",
                electionType: _electionType,
                constituency: _constituency,
                voteCount: 0,
                exists: true
            });
            candidateIds.push(_candidateId);
        }

        // 3. Mark voter commitment as used
        hasVoted[_voterCommitment] = true;

        // 4. Increment tallies
        candidates[_candidateId].voteCount += 1;
        constituencyTotalVotes[_constituency][_electionType] += 1;
        totalVotesRecorded += 1;

        emit VoteStamped(
            _voterCommitment,
            _candidateId,
            _electionType,
            _constituency,
            block.number,
            block.timestamp
        );

        return true;
    }

    /**
     * @dev Verify if a given commitment has already been stamped in the blockchain
     */
    function verifyCommitment(bytes32 _voterCommitment) external view returns (bool) {
        return hasVoted[_voterCommitment];
    }

    /**
     * @dev Get total votes for a candidate directly from blockchain state
     */
    function getCandidateVotes(string memory _candidateId) external view returns (uint256) {
        if (!candidates[_candidateId].exists) {
            return 0;
        }
        return candidates[_candidateId].voteCount;
    }

    /**
     * @dev Return total count of registered candidates
     */
    function getCandidateCount() external view returns (uint256) {
        return candidateIds.length;
    }

    /**
     * @dev Return candidate ID by index
     */
    function getCandidateIdAtIndex(uint256 index) external view returns (string memory) {
        require(index < candidateIds.length, "Index out of bounds");
        return candidateIds[index];
    }
}

